SELECT m1.INDX_SNAME AS `指数名称`, m1.SECCODE AS `指数代码`, ROUND(m1.TCLOSE, 2) AS `最新收盘点位`, ROUND(m2.TCLOSE, 2) AS `去年末收盘点位`, CONCAT(ROUND((m1.TCLOSE - m2.TCLOSE) / m2.TCLOSE * 100, 2), '%') AS `今年以来涨跌幅` FROM INDX_MKT m1 INNER JOIN INDX_MKT m2 ON m1.INNER_CODE = m2.INNER_CODE INNER JOIN GET_INDX_GEN_INFO g ON m1.INNER_CODE = g.INNER_CODE WHERE m1.SECCODE = '399001' AND m1.TRADEDATE = '2026-09-02' AND m1.ISVALID = 1 AND m2.SECCODE = '399001' AND m2.TRADEDATE = (SELECT MAX(TRADEDATE) FROM INDX_MKT WHERE SECCODE = '399001' AND TRADEDATE <= '2025-12-31' AND ISVALID = 1) AND m2.ISVALID = 1 AND g.ISVALID = 1 AND g.USE_STATUS = '使用';
